// Extract articles from API response and filter those with content
const response = $input.first().json;
if (!response.success || !response.data || response.data.length === 0) {
  return []; // No articles to process
}

// Filter articles that have content and no WP post ID yet
const articles = response.data.filter(a => 
  a.content && 
  a.content.trim().length > 50 && 
  !a.wordpress_post_id
);

return articles.map(article => ({
  json: {
    id: article.id,
    title: article.title,
    content: article.content,
    url: article.url,
    source_name: article.source_name,
    published_at: article.published_at || new Date().toISOString()
  }
}));

// Parse the rewritten content from LLM
const raw = $input.first().json.message?.content || $input.first().json.text || '';
const originalArticle = $('Extract Publishable Articles').first().json;

let rewritten;
try {
  let jsonStr = raw;
  const fenceMatch = raw.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (fenceMatch) jsonStr = fenceMatch[1].trim();
  rewritten = JSON.parse(jsonStr);
} catch (e) {
  // If JSON parse fails, use the raw text as content
  rewritten = {
    title: originalArticle.title,
    content: raw
  };
}

return [{
  json: {
    articleId: originalArticle.id,
    originalTitle: originalArticle.title,
    rewrittenTitle: rewritten.title || originalArticle.title,
    rewrittenContent: rewritten.content || raw,
    url: originalArticle.url,
    source_name: originalArticle.source_name,
    published_at: originalArticle.published_at
  }
}];

// Build the WordPress post payload with source attribution
const article = $input.first().json;
const config = $('⚙️ Configuration').first().json;

// Format source attribution block (RTL Arabic)
const attribution = `
<blockquote style="direction: rtl; text-align: right; border-right: 4px solid #3b82f6; padding: 12px; margin: 20px 0; background: #f8f9fa; font-size: 14px;">
  <strong>المصدر:</strong> ${article.source_name}<br>
  <a href="${article.url}" target="_blank" rel="noopener noreferrer">الرابط الأصلي</a>
</blockquote>`;

const fullContent = `<div dir="rtl" style="text-align: right;">
${article.rewrittenContent}
${attribution}
</div>`;

return [{
  json: {
    articleId: article.articleId,
    wpPayload: {
      title: article.rewrittenTitle,
      content: fullContent,
      status: config.wpPostStatus || 'draft',
      date: article.published_at,
      meta: {
        source_url: article.url,
        source_name: article.source_name
      }
    },
    wpUrl: config.wpUrl,
    wpAuth: 'Basic ' + Buffer.from(`${config.wpUsername}:${config.wpAppPassword}`).toString('base64'),
    aggregatorUrl: config.aggregatorUrl
  }
}];

// Update the aggregator DB with WP post ID and rewritten content
const wpResponse = $input.first().json;
const buildPayload = $('Build WP Payload').first().json;

const wpPostId = wpResponse.id || null;
const articleId = buildPayload.articleId;
const aggregatorUrl = buildPayload.aggregatorUrl;

return [{
  json: {
    articleId,
    wpPostId,
    aggregatorUrl,
    updatePayload: {
      content: buildPayload.wpPayload.content,
      status: wpPostId ? 'published' : 'processed',
      wordpress_post_id: wpPostId
    }
  }
}];
